{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} • Aromatherapy Events & Series</title>
  <meta name="description" content="Seasonal ceremonies, small-group workshops, and curated scent journeys — gentle, safety-forward aromatherapy for body and home.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="theme-aura">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" id="mainNav">
        <a href="/services.html">Offerings</a>
        <a href="/blends.html">Blends</a>
        <a href="/shop.html">Shop</a>
        <a href="/pricing.html">Pricing</a>
        <a href="/about.html">About</a>
        <a href="/book.html" class="cta small">{{PRIMARY_CTA_LABEL}}</a>
        <button class="nav-toggle" aria-label="Open menu" id="navToggle">☰</button>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero">
      <svg class="hero-pattern" preserveAspectRatio="none">
        <use href="assets/img/pattern.svg#grid" />
      </svg>
      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1 class="title">A slow inhale — a small ceremony</h1>
          <p class="tag">{{TAGLINE}}</p>
          <p class="lede">Join intimate scent series and seasonal gatherings where aromatics meet quiet intention. Sessions are crafted with care, safety-forward guidance, and simple rituals you can use at home.</p>
          <div class="hero-ctas">
            <a class="cta primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="cta ghost" href="/services.html">Explore gatherings</a>
          </div>
        </div>
        <div class="hero-card">
          <div class="card-inner">
            <h3>Next circle</h3>
            <p class="date">Monthly Series — small cohort</p>
            <p class="meta">Led by {{PRACTITIONER_NAME}} in {{CITY}}, {{STATE}}</p>
            <a class="cta slim ripple" href="/book.html">Reserve a place</a>
          </div>
        </div>
      </div>
    </section>

    <!-- STORY -->
    <section class="story wrap">
      <div class="grid-2">
        <div>
          <h2>Why scent? A gentle introduction</h2>
          <p>Essential oils are concentrated plant expressions used historically for ritual, care, and home comfort. Our offerings present aromatherapy as a sensory companion — not a cure. We prioritize dilution, patch testing, and clear guidance so practices feel safe and sustained.</p>
        </div>
        <div>
          <h3>Our approach</h3>
          <p>Minimalist blends, transparent sourcing, and group formats that center education. Each session includes demonstration, hands-on blending, and take-home guidance so you leave with both scent and confidence.</p>
        </div>
      </div>
    </section>

    <!-- FRAMEWORK (safety & FAQ) -->
    <section class="framework wrap">
      <h2>Practice & safety</h2>
      <p class="sub">Practical notes we share in every event — short, clear, and precautionary.</p>
      <div class="faq-grid">
        <div class="faq">
          <h4>Dilution</h4>
          <p>We recommend conservative dilution rates for topical use (often 1–3% depending on age and sensitivity). Workshop materials include exact recipes and measuring guidance.</p>
        </div>
        <div class="faq">
          <h4>Patch testing</h4>
          <p>Perform a small patch test before topical use — apply diluted blend to forearm and wait 24 hours for any irritation. If redness or discomfort occurs, discontinue use.</p>
        </div>
        <div class="faq">
          <h4>Pets</h4>
          <p>Some essential oils are not safe for animals. We review pet-friendly practices and alternatives, and recommend avoiding direct topical or diffused exposure around sensitive animals.</p>
        </div>
        <div class="faq">
          <h4>Pregnancy & nursing</h4>
          <p>We take a conservative stance: certain oils are avoided during pregnancy and breastfeeding. Please consult with a healthcare provider before using new products; classes include adaptations and non-aromatic options.</p>
        </div>
      </div>
    </section>

    <!-- OFFERS (events_series) -->
    <section class="offers wrap">
      <h2>Series & small gatherings</h2>
      <p class="sub">An events series model: recurring themes, limited seating, hands-on sessions.</p>
      <div class="cards">
        <article class="offer">
          <h3>Seasonal Scent Journey — Series (4 sessions)</h3>
          <p class="desc">Explore seasonal botanicals across four evenings. Learn safe blending, aromatic journaling, and create a personalized roll-on.</p>
          <p class="meta">Includes materials and take-home notes.</p>
          <a class="cta slim" href="/book.html">Join the series</a>
        </article>
        <article class="offer">
          <h3>Intro Workshop — Weekend</h3>
          <p class="desc">A single-day, safety-first workshop focused on basics: dilution, scent families, and simple home blends.</p>
          <a class="cta slim ghost" href="/services.html">Details</a>
        </article>
        <article class="offer">
          <h3>Private Circle — Custom</h3>
          <p class="desc">Invite a small group for a private gathering. Themes, accessibility, and gentle facilitation tailored to your needs.</p>
          <a class="cta slim" href="/book.html">Request a date</a>
        </article>
      </div>
    </section>

    <!-- PRICING teaser -->
    <section class="pricing-preview wrap">
      <h2>Transparent pricing</h2>
      <p class="sub">We keep things simple: clear tiers for series, workshops, and private bookings.</p>
      <div class="price-grid">
        <div class="price">
          <h4>Series</h4>
          <p class="amount">$220</p>
          <p class="note">4 weekly sessions • materials included</p>
        </div>
        <div class="price">
          <h4>Workshop</h4>
          <p class="amount">$85</p>
          <p class="note">Single day • hands-on</p>
        </div>
        <div class="price">
          <h4>Private</h4>
          <p class="amount">Custom</p>
          <p class="note">Contact for quote</p>
        </div>
      </div>
      <a class="cta" href="/pricing.html">See full rates</a>
    </section>

    <!-- TESTIMONIALS -->
    <section class="testimonials wrap">
      <h2>Notes from guests</h2>
      <div class="test-grid">
        <blockquote>
          "The series felt like a quiet reset. Clear instruction and gentle pacing — I keep a roll-on from the first night in my bag." — A.
        </blockquote>
        <blockquote>
          "Practical, safe, and unexpectedly moving. Lovely space and small cohorts." — M.
        </blockquote>
      </div>
    </section>

    <!-- CTA RING (ripple effect) -->
    <section class="cta-wrap">
      <div class="wrap cta-inner">
        <h2>Ready for a small ceremony?</h2>
        <p>Reserve a space in the next series or request a private gathering with {{PRACTITIONER_NAME}}.</p>
        <a class="cta big ripple" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{TAGLINE}}</p>
        <p><a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <div>
        <h4>Navigate</h4>
        <ul>
          <li><a href="/services.html">Offerings</a></li>
          <li><a href="/blends.html">Blends</a></li>
          <li><a href="/shop.html">Shop</a></li>
          <li><a href="/contact.html">Say hello</a></li>
        </ul>
      </div>
      <div>
        <h4>Location</h4>
        <p>{{CITY}}, {{STATE}}</p>
      </div>
    </div>
    <div class="credits wrap">© <span id="year"></span> {{BUSINESS_NAME}} — Mindful aromatics.</div>
  </footer>

  <svg class="visually-hidden" aria-hidden="true">
    <defs>
      <filter id="soft">
        <feGaussianBlur stdDeviation="6" />
      </filter>
    </defs>
  </svg>
</body>
</html>"} 
