{"path":"assets/css/styles.css","content":"/* Minimal poetic aura theme for aromatherapy events */
:root{
  --bg:#fffefb;
  --muted:#6b6b6b;
  --accent-start:#7dd3fc;
  --accent-end:#b794f4;
  --card:#ffffff;
  --glass:rgba(255,255,255,0.6);
  --shadow: 0 6px 20px rgba(18,18,18,0.08);
  --radius:14px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,'Helvetica Neue',Arial;line-height:1.5;color:#1b1b1b;background:linear-gradient(180deg,var(--bg),#f7f3ff);}
.wrap{max-width:1000px;margin:0 auto;padding:28px}
.site-header{backdrop-filter: blur(6px);position:sticky;top:0;background:linear-gradient(180deg,rgba(255,255,255,0.85),rgba(255,255,255,0.6));border-bottom:1px solid rgba(20,20,20,0.03);z-index:40}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;text-decoration:none;color:#111;padding:6px 0}
.nav a{margin-left:16px;color:var(--muted);text-decoration:none}
.nav .cta.small{background:linear-gradient(90deg,var(--accent-start),var(--accent-end));padding:8px 12px;border-radius:10px;color:white;text-decoration:none}
.nav-toggle{display:none}

.hero{position:relative;overflow:hidden;padding:60px 0 40px}
.hero-pattern{position:absolute;inset:0;width:100%;height:100%;opacity:0.12}
.hero-inner{display:grid;grid-template-columns:1fr 340px;gap:28px;align-items:center}
.title{font-weight:700;font-size:32px;margin:0 0 10px}
.tag{color:var(--muted);margin:0 0 14px}
.lede{color:#333}
.hero-card{background:linear-gradient(180deg,rgba(255,255,255,0.75),var(--card));border-radius:var(--radius);box-shadow:var(--shadow);padding:18px}
.card-inner h3{margin:0 0 6px}
.card-inner .date{font-size:13px;color:var(--muted)}
.hero-ctas{margin-top:18px}
.cta{display:inline-block;padding:10px 16px;border-radius:12px;text-decoration:none}
.cta.primary{background:linear-gradient(90deg,var(--accent-start),var(--accent-end));color:#fff}
.cta.ghost{border:1px solid rgba(0,0,0,0.06);color:var(--muted);background:transparent}
.cta.slim{padding:8px 12px;border-radius:10px;background:var(--card);box-shadow:var(--shadow);text-decoration:none}
.cta.big{padding:16px 22px;border-radius:16px;font-weight:600}
.ripple{position:relative;overflow:hidden}
.ripple::after{content:"";position:absolute;border-radius:50%;transform:scale(0);opacity:0.32;background:radial-gradient(circle at center, rgba(255,255,255,0.6), transparent 40%);transition:transform .6s,opacity .8s}
.ripple:active::after{transform:scale(6);opacity:0}

.story{padding-top:20px;padding-bottom:20px}
.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:20px}
.framework{background:linear-gradient(180deg,rgba(247,243,255,0.6),transparent);padding:28px;border-radius:12px}
.faq-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}
.faq{background:var(--card);padding:14px;border-radius:10px}

.offers .cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:12px}
.offer{background:var(--card);padding:16px;border-radius:12px;box-shadow:var(--shadow)}
.pricing-preview{padding:24px}
.price-grid{display:flex;gap:14px}
.price{background:var(--card);padding:12px;border-radius:10px;flex:1}

.testimonials{padding:22px}
.test-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
blockquote{background:linear-gradient(180deg,rgba(255,255,255,0.9),#fff);padding:16px;border-left:4px solid rgba(123,97,255,0.14);border-radius:8px}

.cta-wrap{padding:36px 0;background:linear-gradient(90deg,rgba(125,211,252,0.08),rgba(183,148,244,0.06));border-radius:12px;margin:24px 0}
.cta-inner{text-align:center}

.footer-grid{display:grid;grid-template-columns:1fr 160px 140px;gap:16px;padding:20px 0}
.site-footer{border-top:1px solid rgba(0,0,0,0.04);background:transparent}
.credits{font-size:13px;color:var(--muted);padding:14px 28px}

.visually-hidden{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}

/* Responsive */
@media (max-width:900px){
  .hero-inner{grid-template-columns:1fr}
  .grid-2{grid-template-columns:1fr}
  .offers .cards{grid-template-columns:1fr}
  .faq-grid{grid-template-columns:1fr}
  .nav a{display:none}
  .nav-toggle{display:inline-block;background:none;border:none;font-size:20px}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Simple UI behaviors: year, nav toggle, smooth scroll
  document.addEventListener('DOMContentLoaded', function(){
    var y = document.getElementById('year'); if(y) y.textContent = new Date().getFullYear();
    var toggle = document.getElementById('navToggle');
    var nav = document.getElementById('mainNav');
    if(toggle && nav){
      toggle.addEventListener('click', function(){
        nav.classList.toggle('expanded');
        toggle.setAttribute('aria-expanded', nav.classList.contains('expanded') ? 'true' : 'false');
      });
    }

    // Smooth scroll for internal links
    document.querySelectorAll('a[href^="#"]').forEach(function(a){
      a.addEventListener('click', function(e){
        e.preventDefault();
        var id = this.getAttribute('href').slice(1);
        var el = document.getElementById(id);
        if(el) el.scrollIntoView({behavior:'smooth'});
      });
    });

    // Ripple effect: create circle on click
    document.querySelectorAll('.ripple').forEach(function(btn){
      btn.addEventListener('click', function(e){
        var rect = btn.getBoundingClientRect();
        var circle = document.createElement('span');
        var diameter = Math.max(rect.width, rect.height);
        var radius = diameter/2;
        circle.style.width = circle.style.height = diameter + 'px';
        circle.style.left = (e.clientX - rect.left - radius) + 'px';
        circle.style.top = (e.clientY - rect.top - radius) + 'px';
        circle.classList.add('ripple-effect');
        circle.style.position = 'absolute';
        circle.style.borderRadius = '50%';
        circle.style.transform = 'scale(0)';
        circle.style.background = 'rgba(255,255,255,0.35)';
        circle.style.pointerEvents = 'none';
        circle.style.transition = 'transform 600ms, opacity 900ms';
        btn.appendChild(circle);
        requestAnimationFrame(function(){ circle.style.transform = 'scale(4)'; circle.style.opacity = '0'; });
        setTimeout(function(){ try{ btn.removeChild(circle); }catch(e){} }, 1000);
      });
    });

  });
})();"} 
